from pathlib import Path
root=Path(__file__).resolve().parent.parent
markup='''<style>.columns{display:grid;grid-template-columns:1fr 1fr;gap:24px}.left,.comments{min-height:300px}.s4t-comment-search-slot{width:320px}</style><div data-testid="card-back"><header><textarea data-testid="card-back-title-input">Card title</textarea><div class="s4t-comment-search-slot"><div class="s4t-comment-navigator"><input placeholder="Find in comments"></div></div><button>Cover</button></header><div class="columns"><section class="left"><div class="js-edit-desc" role="button"><div class="description-content" role="button"><div class="ak-renderer-document">Description</div></div></div><textarea>Unchanged</textarea></section><section class="comments"><h3>Comments &amp; activity</h3><div role="button"><div class="ak-renderer-document">Tech Design review text</div></div><div contenteditable="true">Draft</div></section></div></div><pre id="result">RUNNING</pre>'''
tests='''setTimeout(async()=>{const errors=[],check=(v,m)=>{if(!v)errors.push(m)},wait=ms=>new Promise(r=>setTimeout(r,ms));try{const left=document.querySelector('.left'),comments=document.querySelector('.comments'),editor=comments.querySelector('[contenteditable]'),button=document.querySelector('.s4t-comment-layout-toggle'),search=document.querySelector('.s4t-comment-navigator');const initial=comments.getBoundingClientRect().width;check(button.nextElementSibling.classList.contains('s4t-review-marker')&&document.querySelector('.s4t-review-marker').nextElementSibling===search,'controls before search');check(search.getBoundingClientRect().left-document.querySelector('.s4t-review-marker').getBoundingClientRect().right<=5,'no toolbar gap');const standaloneMarker=document.querySelector('.s4t-review-marker');check(!standaloneMarker.hidden,'marker always visible');standaloneMarker.click();const description=left.querySelector('.description-content');description.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,cancelable:true,pointerId:8,button:0,clientX:20,clientY:100}));check(!!document.querySelector('#s4t-review-ink'),'description can be marked outside review');description.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,pointerId:8}));let descriptionEdits=0;description.addEventListener('click',()=>descriptionEdits++);description.addEventListener('dblclick',()=>descriptionEdits++);
for(const type of ['mousedown','click','dblclick']){const event=new MouseEvent(type,{bubbles:true,cancelable:true});description.dispatchEvent(event);check(event.defaultPrevented,'description '+type+' blocked while marking');}check(descriptionEdits===0,'drawing does not trigger native description edit');
let wrapperEvents=0;const wrapper=description.parentElement;['pointerdown','pointerup','mousedown','mouseup','click','dblclick'].forEach(type=>wrapper.addEventListener(type,()=>wrapperEvents++));
const body=description.querySelector('.ak-renderer-document');body.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,cancelable:true,pointerId:18,button:0}));body.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,cancelable:true,pointerId:18,button:0}));for(const type of ['mousedown','mouseup','click','dblclick'])body.dispatchEvent(new MouseEvent(type,{bubbles:true,cancelable:true}));check(wrapperEvents===0,'description wrappers cannot receive drawing or click events');
// Modern description: generated wrapper, read-only textbox role, no legacy selector.
description.className='generated-description';description.setAttribute('role','textbox');wrapper.className='generated-wrapper';
let nativeMouseDown=0;const nativeEdit=event=>{if(description.contains(event.target))nativeMouseDown++;};document.addEventListener('mousedown',nativeEdit,true);
body.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,cancelable:true,pointerId:19,button:0}));body.dispatchEvent(new MouseEvent('mousedown',{bubbles:true,cancelable:true}));body.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,cancelable:true,pointerId:19,button:0}));check(nativeMouseDown===0,'modern renderer mousedown cannot open editor');check(standaloneMarker.getAttribute('aria-pressed')==='true','mousedown keeps marker active');document.removeEventListener('mousedown',nativeEdit,true);
description.className='description-content';description.setAttribute('role','button');wrapper.className='js-edit-desc';
const editButton=document.createElement('button');editButton.textContent='Edit';description.appendChild(editButton);let explicitEdits=0;editButton.onclick=()=>explicitEdits++;editButton.click();check(explicitEdits===1,'explicit description Edit remains usable');editButton.remove();
standaloneMarker.click();description.click();check(descriptionEdits===2,'description click restored with marker off');standaloneMarker.click();
const title=document.querySelector('[data-testid="card-back-title-input"]');title.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,cancelable:true,pointerId:9,button:0,clientX:30,clientY:20}));check(document.querySelectorAll('#s4t-review-ink g').length===1,'idle title can be marked');title.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,pointerId:9}));title.focus();check(standaloneMarker.disabled&&standaloneMarker.getAttribute('aria-pressed')==='false','title editing disables marker');check(title.value==='Card title','title value unchanged');button.focus();const searchWidth=search.getBoundingClientRect().width;button.click();check(Math.abs(search.getBoundingClientRect().width-searchWidth)<1,'review keeps search width');check(!document.querySelector('.s4t-review-clear'),'no erase button');check(getComputedStyle(left).display==='none','left section hidden');check(comments.getBoundingClientRect().width>initial*1.8,'comments fill card');check(editor.isConnected&&editor.textContent==='Draft','native editor untouched');check(getComputedStyle(comments).userSelect==='none','review prevents text selection');check(getComputedStyle(editor).userSelect==='text','editor selection preserved');check(button.getAttribute('aria-pressed')==='true','active state');check(button.getAttribute('aria-label').includes('Review mode'),'review name');const marker=document.querySelector('.s4t-review-marker');check(!marker.hidden,'marker available in review');check(marker.getAttribute('aria-pressed')==='true','marker on by default');const text=comments.querySelector('.ak-renderer-document'),original=text.innerHTML,r=text.getBoundingClientRect();text.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,cancelable:true,pointerId:1,button:0,clientX:r.left+5,clientY:r.top+5}));text.dispatchEvent(new PointerEvent('pointermove',{bubbles:true,pointerId:1,clientX:r.left+80,clientY:r.top+5}));text.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,pointerId:1}));check(document.querySelectorAll('#s4t-review-ink path').length===3,'laser glow, red stroke and bright core');check(text.innerHTML===original,'comment unchanged');check(document.querySelector('#s4t-review-ink path').getAttribute('d').includes('Q'),'smoothed stroke');check(document.querySelector('#s4t-review-ink path:nth-child(2)').getAttribute('stroke-width')==='3','thin stroke');check(!document.querySelector('.s4t-review-spark'),'no detached sparkles');check(!!document.querySelector('.s4t-review-laser-glow'),'glow stays on stroke');check(document.querySelector('#s4t-review-ink-layer').matches(':popover-open'),'ink visible in top layer');check(document.querySelector('[data-testid="card-back"]').contains(document.querySelector('#s4t-review-ink')),'ink inside card dialog');await wait(1600);check(!document.querySelector('#s4t-review-ink'),'marks auto disappear');editor.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:2,button:0}));check(!document.querySelector('#s4t-review-ink'),'editor unaffected');editor.focus();check(marker.disabled&&marker.getAttribute('aria-pressed')==='false','editing automatically disables marker');const selected=new Event('selectstart',{bubbles:true,cancelable:true});text.dispatchEvent(selected);check(selected.defaultPrevented,'comment selection blocked');const editSelected=new Event('selectstart',{bubbles:true,cancelable:true});editor.dispatchEvent(editSelected);check(!editSelected.defaultPrevented,'editing selection allowed');button.focus();check(!marker.disabled,'marker available after editing loses focus');marker.click();document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true,cancelable:true}));check(marker.getAttribute('aria-pressed')==='false','escape stops marker');button.click();check(getComputedStyle(left).display!=='none','left restored');check(!comments.classList.contains('s4t-review-no-selection'),'normal text selection restored');check(Math.abs(comments.getBoundingClientRect().width-initial)<2,'original width restored');check(left.querySelector('textarea').value==='Unchanged','left content unchanged');button.click();window.s4tPreferences={enabled:()=>false};document.dispatchEvent(new Event('s4t-preferences-changed'));check(!left.classList.contains('s4t-comment-left-hidden'),'disabled review restores layout');check(marker.getAttribute('aria-pressed')==='false','disabled laser stops pointer');marker.click();check(marker.getAttribute('aria-pressed')==='false','disabled laser cannot restart');window.s4tPreferences.enabled=()=>true;button.click();document.querySelector('[data-testid="card-back"]').remove();await wait(100);check(!left.classList.contains('s4t-comment-left-hidden'),'card close clears layout');}catch(e){errors.push(e.stack)}document.querySelector('#result').textContent=errors.length?'FAIL: '+errors.join('; '):'PASS: toolbar order, expand, restore, unchanged native editor and close cleanup';},150);'''
Path('/tmp/s4t-comment-layout-ui.html').write_text('<html><body>'+markup+'<script>'+(root/'comment-layout.js').read_text()+tests+'</script></body></html>')
